    [Xunit.Fact]
    public static void TestEveryPackOfTheCatalogueIsSoundAndNamesAnEngineOfTheTable() {
        emon.Testport.AssertEq(Engines.PkPackCount(), 24, "20 language models, OSD and the three PP-OCR models");
        int p = 1;
        int files = 0;
        int langs = 0;
        while (p <= Engines.PkPackCount()) {
            System.Text.StringBuilder t = emon.Testport.NewText();
            System.Text.StringBuilder lic = emon.Testport.NewText();
            int eng = Engines.PkPackEngine(p);
            int kind = Engines.PkPackKind(p);
            int sum = 0;
            int i = 0;
            int n = 0;
            emon.Testport.AssertEq(Engines.PkPackKnown(p), 1, "known");
            emon.Testport.AssertEq(Packdata.PkidEmitName(t, p), 1, "a pack has an id");
            emon.Testport.AssertEq(Packdata.PlicEmitName(lic, Engines.PkPackLicence(p)), 1, "and a licence");
            emon.Testport.AssertEq(Packdata.PkidFind(emon.Testport.TextBlob("tess-osd"), 0, 8), Packdata.PkidTessOsd(), "ids are found by name");
            emon.Testport.AssertThat((eng == 0) || (Engines.PkEngineKnown(eng) == 1), "a pack is for an engine of the table, or for any");
            emon.Testport.AssertThat(Engines.PkPackRev(p) > 0, "a revision");
            emon.Testport.AssertThat((kind == Engines.PkindRecognizer()) || ((kind == Engines.PkindOsd()) || ((kind == Engines.PkindDetector()) || (kind == Engines.PkindClassifier()))), "a known kind");
            if (eng != 0) {
                emon.Testport.AssertThat((Engines.PkEngineNeeds(eng) & kind) != 0, "the engine it is for reads with that kind of pack");
            }
            emon.Testport.AssertThat(Engines.PkPackFileCount(p) > 0, "files");
            while (i < Engines.PkPackFileCount(p)) {
                sum += Engines.PkPackFileBytes(p, i);
                emon.Testport.AssertThat(Engines.PkPackFileBytes(p, i) > 0, "a file has a size");
                emon.Testport.AssertEq(EnShaNonzero(p, i), 1, "and a hash");
                emon.Testport.AssertThat(Engines.PkPackFileName(p, i, emon.Testport.NewText()) > 0, "and a name");
                files += 1;
                i += 1;
            }
            emon.Testport.AssertEq(sum, Engines.PkPackBytes(p), "the pack's size is its files'");
            i = 0;
            while (i < 21) {
                if (Packdata.PackLangs[i * 2 + 0] == p) {
                    n += 1;
                }
                i += 1;
            }
            langs += n;
            if (kind == Engines.PkindRecognizer()) {
                emon.Testport.AssertThat(n > 0, "a recognizer reads a language");
            } else {
                emon.Testport.AssertEq(n, 0, "only a recognizer reads a language");
            }
            p += 1;
        }
        emon.Testport.AssertEq(files, 24, "every file row belongs to a pack, in order");
        emon.Testport.AssertEq(langs, 21, "every language row belongs to a pack");
    }
